pragma solidity ^0.8.30;

/// @notice B0 experiment grammar. No standing plan registry or publication authority.
library LensPlan {
    bytes32 internal constant EXPERIMENT_PLAN_TYPE = 0x05cc2a7f4eec5faff7e64f2f8374aca5f980d390fd4eee3b46c2f5c53853e61e;
    bytes32 internal constant SEMANTICS_PROFILE_B0 = keccak256("efs2/lens-semantics/b0/1");
    uint16 internal constant WINNER_NONE = 0xffff;

    enum Presence {
        UNKNOWN,
        FOUND,
        ABSENT,
        CONFLICT,
        UNSUPPORTED
    }

    struct BasisReport {
        bytes32 realmRevisionId;
        uint64 blockNumber;
        uint64 admissionHigh;
        uint8 basisKind;
    }

    struct ResolvedTarget {
        uint8 targetKind;
        bytes32 targetA;
        uint16 targetLeaf;
    }

    struct ResolveResult {
        Presence presence;
        uint8 reasonCode;
        ResolvedTarget target;
        uint16 winnerIndex;
        uint16 winnerTier;
        uint64 winnerAdmissionOrdinal;
        uint16 presentCount;
        uint16 agreeCount;
        BasisReport basis;
    }

    struct Entry {
        bytes32 principalId;
        uint16 tier;
    }

    struct Plan {
        uint8 combiner;
        uint16 thresholdK;
        bytes32 purposeAndScope;
        bytes32 semanticsProfileId;
        Entry[] entries;
    }

    function validate(bytes32 typeId, bytes memory b) internal pure returns (uint8) {
        if (typeId != EXPERIMENT_PLAN_TYPE) return 1;
        if (b.length < 98 || u16(b, 0) != b.length - 2) return 2;
        uint16 n = u16(b, 8);
        if (b.length != 98 + 64 * uint256(n)) return 2;
        if (b[2] != 0x01) return 3;
        uint8 combiner = uint8(b[3]);
        if (combiner > 2) return 4;
        if (uint8(b[4]) & 0xfe != 0) return 5;
        // Structural-code order is global, not entry-local. Even an over-cap
        // frame checks entry flags first; the canonical u16 length bounds this
        // scan to 1,022 entries (the retained Record reader bounds it further).
        for (uint256 i; i < n; ++i) {
            if (u16(b, 132 + 64 * i) != 0) return 5;
        }
        uint16 k = u16(b, 6);
        if (combiner == 2 ? (k == 0 || k > n) : k != 0) return 6;
        if (n == 0 || n > 64) return 7;
        bool duplicate;
        bool reserved = b[5] != 0 || uint256(word(b, 2)) & ((uint256(1) << 192) - 1) != 0;
        bool badTier;
        bool tiedTier;
        bool authFloor;
        for (uint256 i; i < n; ++i) {
            uint256 at = 98 + 64 * i;
            bytes32 principal = word(b, at);
            uint256 metadata = uint256(word(b, at + 32));
            uint16 tier = u16(b, at + 32);
            if (i != 0) {
                uint16 previousTier = u16(b, at - 32);
                if (tier < previousTier || (tier == previousTier && principal <= word(b, at - 64))) return 8;
                if (tier == previousTier) tiedTier = true;
            }
            for (uint256 j; j < i; ++j) {
                if (principal == word(b, 98 + 64 * j)) duplicate = true;
            }
            if (metadata & ((uint256(1) << 160) - 1) != 0) reserved = true;
            if (tier != 0) badTier = true;
            if ((metadata >> 160) & type(uint64).max != 0) authFloor = true;
        }
        if (duplicate) return 9;
        if (reserved) return 10;
        if (combiner != 1 && badTier) return 11;
        if (uint8(b[4]) & 1 != 0 && tiedTier) return 12;
        if (authFloor) return 13;
        return 0;
    }

    /// @dev Call only after validate returned zero.
    function decode(bytes memory b) internal pure returns (Plan memory p) {
        p.combiner = uint8(b[3]);
        p.thresholdK = u16(b, 6);
        p.purposeAndScope = word(b, 34);
        p.semanticsProfileId = word(b, 66);
        uint16 n = u16(b, 8);
        p.entries = new Entry[](n);
        for (uint256 i; i < n; ++i) {
            p.entries[i] = Entry(word(b, 98 + 64 * i), u16(b, 130 + 64 * i));
        }
    }

    function deriveBindingKey(bytes32 principalId, bytes32 positionKey) internal pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("efs2/binding/1"), principalId, positionKey));
    }

    function u16(bytes memory b, uint256 at) private pure returns (uint16) {
        return (uint16(uint8(b[at])) << 8) | uint16(uint8(b[at + 1]));
    }

    function word(bytes memory b, uint256 at) private pure returns (bytes32 value) {
        assembly ("memory-safe") { value := mload(add(add(b, 32), at)) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {BindingFold} from "./BindingFold.sol";

library Preparation {
    struct Config {
        address helper;
        bytes32 codehash;
    }

    struct CompiledType {
        bytes32 typeId;
        bytes cacheBytes;
    }

    struct CompiledGroup {
        bytes32 groupHash;
        bytes32 rawHash;
        CompiledType[] types;
        bytes32[] dependencies;
    }

    struct PreparedRef {
        uint8 roleIndex;
        uint8 targetClass;
        bytes32 expectedType;
        bytes32 targetId;
        uint16 leafIndex;
    }

    struct PreparedRecord {
        PreparedRef[] references;
        bytes32[] occurrenceKeys;
        BindingFold.Effect effect;
    }
    error HelperIdentity();
    error HelperOutput(uint256 length);
    error HelperInput(uint256 length);
    error InvalidPreparation();
    // PROVISIONAL experiment ceilings, not final C0 caps.
    uint256 internal constant GROUP_OUTPUT = 131072;
    uint256 internal constant PREPARED_OUTPUT = 8192;
    uint256 internal constant INPUT_MAX = 163840;
    uint256 internal constant GROUP_GAS = 15000000;
    uint256 internal constant PREPARE_GAS = 5000000;

    function invoke(Config memory c, bytes memory input, uint256 maximum, uint256 gasLimit)
        internal
        view
        returns (bytes memory output)
    {
        if (c.helper.code.length == 0 || c.helper.codehash != c.codehash) revert HelperIdentity();
        if (input.length > INPUT_MAX) revert HelperInput(input.length);
        bool ok;
        uint256 n;
        address target = c.helper;
        assembly ("memory-safe") {
            ok := staticcall(gasLimit, target, add(input, 32), mload(input), 0, 0)
            n := returndatasize()
        }
        if (n > (ok ? maximum : 1024)) revert HelperOutput(n);
        output = new bytes(n);
        assembly ("memory-safe") { returndatacopy(add(output, 32), 0, n) }
        if (!ok) assembly ("memory-safe") { revert(add(output, 32), mload(output)) }
    }

    function intrinsic(Config memory c, bytes memory raw) internal view returns (CompiledType memory) {
        return
            abi.decode(
                invoke(c, abi.encodeCall(IPreparation.compileIntrinsic, (raw)), GROUP_OUTPUT, GROUP_GAS), (CompiledType)
            );
    }

    function group(Config memory c, bytes memory raw) internal view returns (CompiledGroup memory) {
        CompiledGroup memory g = abi.decode(
            invoke(c, abi.encodeCall(IPreparation.compileGroup, (raw)), GROUP_OUTPUT, GROUP_GAS), (CompiledGroup)
        );
        if (g.types.length == 0 || g.types.length > 16 || g.dependencies.length > 256) revert InvalidPreparation();
        return g;
    }

    function record(
        Config memory c,
        bytes memory cache,
        bytes32 typeId,
        bytes memory body,
        bytes32 recordId,
        bytes32 principal,
        BindingFold.KernelIds memory ids,
        bool bodyOnly
    ) internal view returns (PreparedRecord memory r) {
        r = abi.decode(
            invoke(
                c,
                abi.encodeCall(IPreparation.prepareRecord, (cache, typeId, body, recordId, principal, ids, bodyOnly)),
                PREPARED_OUTPUT,
                PREPARE_GAS
            ),
            (PreparedRecord)
        );
        if (r.references.length > 16 || r.occurrenceKeys.length > 43) revert InvalidPreparation();
    }
}

interface IPreparation {
    function compileIntrinsic(bytes calldata raw) external view returns (Preparation.CompiledType memory);
    function compileGroup(bytes calldata raw) external view returns (Preparation.CompiledGroup memory);
    function prepareRecord(
        bytes calldata cache,
        bytes32 typeId,
        bytes calldata body,
        bytes32 recordId,
        bytes32 principal,
        BindingFold.KernelIds calldata ids,
        bool bodyOnly
    ) external view returns (Preparation.PreparedRecord memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {TypeGroupParser} from "C0Admission/TypeGroupParser.sol";

library RecordBody {
    struct ReferenceValue {
        uint8 roleIndex;
        bytes32 targetId;
        uint16 leafIndex;
    }

    struct CheckedBody {
        bytes[] fields;
        ReferenceValue[] references;
    }
    error InvalidBody(uint16 code);

    struct Cursor {
        bytes data;
        uint256 pos;
    }

    struct Descriptor {
        uint8 kind;
        uint256 arg;
        bool hasRef;
        Descriptor[] children;
    }

    struct Walk {
        Cursor body;
        ReferenceValue[] refs;
        uint256 count;
    }

    /// @dev Consumes an admitted TypeGroupParser cache, not an untrusted schema on-ramp.
    /// No target existence, occurrence membership, Principal semantics, NFC or Files claims.
    function validate(TypeGroupParser.SchemaCache memory s, bytes memory body)
        internal
        pure
        returns (CheckedBody memory checked)
    {
        if (body.length > 8192) revert InvalidBody(3);
        checked.fields = new bytes[](s.fields.length);
        Walk memory w = Walk(Cursor(body, 0), new ReferenceValue[](16), 0);
        for (uint256 i; i < s.fields.length; ++i) {
            Cursor memory dc = Cursor(s.fields[i].descriptor, 0);
            Descriptor memory d = descriptor(dc, 1);
            if (dc.pos != dc.data.length || d.kind != s.fields[i].kind) revert InvalidBody(13);
            uint256 roleIndex = 256;
            for (uint256 j; j < s.roles.length; ++j) {
                if (s.roles[j].fieldIdx != i) continue;
                if (roleIndex != 256 || j >= 16) revert InvalidBody(16);
                roleIndex = j;
            }
            if (d.hasRef || roleIndex != 256) {
                uint8 leaf = d.kind == 11 || d.kind == 14 ? d.children[0].kind : d.kind;
                if (
                    roleIndex == 256 || !(d.kind == 7 || d.kind == 8 || d.kind == 11 || d.kind == 14)
                        || !(leaf == 7 || leaf == 8) || (d.kind == 11 && leaf != 7)
                ) revert InvalidBody(16);
                uint8 cls = s.roles[roleIndex].targetClass;
                if (cls < 1 || cls > 5 || ((leaf == 8) != (cls == 4))) revert InvalidBody(16);
            }
            uint256 start = w.body.pos;
            decode(d, w, 1, roleIndex);
            checked.fields[i] = slice(body, start, w.body.pos - start);
        }
        if (w.body.pos != body.length) revert InvalidBody(1);
        for (uint256 i; i < s.roles.length; ++i) {
            if (s.roles[i].fieldIdx >= s.fields.length) revert InvalidBody(16);
        }
        constraints(s, checked.fields);
        checked.references = new ReferenceValue[](w.count);
        for (uint256 i; i < w.count; ++i) {
            checked.references[i] = w.refs[i];
        }
    }

    function descriptor(Cursor memory c, uint256 depth) private pure returns (Descriptor memory d) {
        if (depth > 4) revert InvalidBody(11);
        skip(c, number(c, 2, 13), 13); // Names were checked at descriptor admission.
        d.kind = uint8(number(c, 1, 13));
        uint8 k = d.kind;
        if (k >= 2 && k <= 4) {
            d.arg = number(c, 1, 13);
            if (k == 4
                    ? d.arg == 0 || d.arg > 32
                    : !(d.arg == 1 || d.arg == 2 || d.arg == 4 || d.arg == 8 || d.arg == 16 || d.arg == 32)) revert InvalidBody(13);
        } else if (k == 5 || k == 6) {
            d.arg = number(c, 2, 13);
            if (d.arg > (k == 5 ? 8192 : 4096)) revert InvalidBody(13);
        } else if (k == 11 || k == 12 || k == 13 || k == 14) {
            d.arg = k == 14 ? 0 : number(c, 2, 13);
            if ((k == 11 && d.arg > 1024) || (k == 12 && d.arg > 256) || (k == 13 && (d.arg == 0 || d.arg > 64))) {
                revert InvalidBody(13);
            }
            uint256 n = k == 12 ? 2 : k == 13 ? d.arg : 1;
            d.children = new Descriptor[](n);
            for (uint256 i; i < n; ++i) {
                // Stage A runtime OPTION does not add a container depth. The existing
                // admission parser is more conservative; this does not broaden its on-ramp.
                d.children[i] = descriptor(c, k == 14 ? depth : depth + 1);
                d.hasRef = d.hasRef || d.children[i].hasRef;
            }
            if (k == 12 && !(d.children[0].kind >= 2 && d.children[0].kind <= 6)) revert InvalidBody(13);
        } else if (k == 7 || k == 8) {
            d.hasRef = true;
        } else if (!(k == 1 || k == 9 || k == 10)) {
            revert InvalidBody(13);
        }
    }

    function decode(Descriptor memory d, Walk memory w, uint256 depth, uint256 roleIndex) private pure {
        if (depth > 4) revert InvalidBody(11);
        Cursor memory c = w.body;
        uint8 k = d.kind;
        if (k == 1) {
            if (number(c, 1, 2) > 1) revert InvalidBody(7);
        } else if (k >= 2 && k <= 4) {
            skip(c, d.arg, 2);
        } else if (k == 5 || k == 6) {
            uint256 n = number(c, 2, 2);
            if (n > d.arg) revert InvalidBody(3);
            uint256 start = c.pos;
            skip(c, n, 2);
            if (k == 6) utf8(c.data, start, n, false);
        } else if (k == 7 || k == 8) {
            // OCCREF is one full-width envelope word and uint16 leaf, never two roles.
            need(c, k == 7 ? 32 : 34, 2);
            bytes32 target = bytes32(number(c, 32, 2));
            uint16 leaf = k == 8 ? uint16(number(c, 2, 2)) : 0;
            if (k == 7 && uint256(target) < 65536) revert InvalidBody(8);
            if (w.count == 16) revert InvalidBody(15);
            if (roleIndex == 256) revert InvalidBody(16);
            w.refs[w.count++] = ReferenceValue(uint8(roleIndex), target, leaf);
        } else if (k == 9) {
            skip(c, 32, 2);
        } else if (k == 10) {
            need(c, 4, 2);
            uint256 alg = number(c, 2, 2);
            uint256 n = number(c, 2, 2);
            uint256 expected = alg == 17 || alg == 61185 ? 20 : alg == 18 || alg == 27 ? 32 : alg == 19 ? 64 : 0;
            if (expected == 0 || n != expected) revert InvalidBody(9);
            skip(c, n, 2);
        } else if (k == 11 || k == 12) {
            uint256 n = number(c, 2, 2);
            if (n > d.arg) revert InvalidBody(12);
            bytes memory previous;
            for (uint256 i; i < n; ++i) {
                uint256 start = c.pos;
                decode(d.children[0], w, depth + 1, roleIndex);
                if (k == 12) {
                    bytes memory key = slice(c.data, start, c.pos - start);
                    if (i != 0 && !less(previous, key)) revert InvalidBody(5);
                    previous = key;
                    decode(d.children[1], w, depth + 1, roleIndex);
                }
            }
        } else if (k == 13) {
            for (uint256 i; i < d.children.length; ++i) {
                decode(d.children[i], w, depth + 1, roleIndex);
            }
        } else if (k == 14) {
            uint256 flag = number(c, 1, 2);
            if (flag > 1) revert InvalidBody(6);
            if (flag == 1) decode(d.children[0], w, depth, roleIndex);
        } else {
            revert InvalidBody(13);
        }
    }

    function constraints(TypeGroupParser.SchemaCache memory s, bytes[] memory fields) private pure {
        for (uint256 i; i < s.constraints.length; ++i) {
            TypeGroupParser.ConstraintCache memory x = s.constraints[i];
            if (x.fieldIdx >= fields.length) revert InvalidBody(13);
            uint8 kind = s.fields[x.fieldIdx].kind;
            Cursor memory c = Cursor(fields[x.fieldIdx], 0);
            if (x.kind == 1) {
                if (!(kind == 2 || kind == 3) || x.min > x.max) revert InvalidBody(13);
                uint256 n = c.data.length;
                uint256 raw = number(c, n, 13);
                if (kind == 2) {
                    // Do not cast a UINT(32) above INT256_MAX to a negative value.
                    if (x.max < 0 || raw > uint256(x.max) || (x.min > 0 && raw < uint256(x.min))) {
                        revert InvalidBody(14);
                    }
                } else {
                    if (n < 32 && (raw & (uint256(1) << (n * 8 - 1))) != 0) raw |= type(uint256).max << (n * 8);
                    int256 value = int256(raw);
                    if (value < x.min || value > x.max) revert InvalidBody(14);
                }
            } else if (x.kind == 2) {
                if (!(kind == 5 || kind == 6 || kind == 11 || kind == 12)) revert InvalidBody(13);
                if (number(c, 2, 13) == 0) revert InvalidBody(14);
            } else if (x.kind == 3) {
                if (kind != 6) revert InvalidBody(13);
                uint256 n = number(c, 2, 13);
                if (n == 0) revert InvalidBody(14);
                utf8(c.data, 2, n, true);
            } else {
                revert InvalidBody(13);
            }
        }
    }

    function utf8(bytes memory b, uint256 start, uint256 n, bool name) private pure {
        uint256 end = start + n;
        for (uint256 i = start; i < end;) {
            uint256 first = uint8(b[i++]);
            uint256 cp;
            uint256 rest;
            uint256 min;
            if (first < 128) {
                cp = first;
            } else if (first >= 194 && first <= 223) {
                cp = first & 31;
                rest = 1;
                min = 128;
            } else if (first >= 224 && first <= 239) {
                cp = first & 15;
                rest = 2;
                min = 2048;
            } else if (first >= 240 && first <= 244) {
                cp = first & 7;
                rest = 3;
                min = 65536;
            } else {
                revert InvalidBody(4);
            }
            if (rest > end - i) revert InvalidBody(4);
            for (uint256 j; j < rest; ++j) {
                uint256 next = uint8(b[i++]);
                if (next < 128 || next > 191) revert InvalidBody(4);
                cp = (cp << 6) | (next & 63);
            }
            if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) revert InvalidBody(4);
            if (name && (cp < 32 || (cp >= 127 && cp <= 159))) revert InvalidBody(14);
        }
    }

    function less(bytes memory a, bytes memory b) private pure returns (bool) {
        uint256 n = a.length < b.length ? a.length : b.length;
        for (uint256 i; i < n; ++i) {
            if (a[i] != b[i]) return uint8(a[i]) < uint8(b[i]);
        }
        return a.length < b.length;
    }

    function need(Cursor memory c, uint256 n, uint16 code) private pure {
        if (n > c.data.length - c.pos) revert InvalidBody(code);
    }

    function skip(Cursor memory c, uint256 n, uint16 code) private pure {
        need(c, n, code);
        c.pos += n;
    }

    function number(Cursor memory c, uint256 n, uint16 code) private pure returns (uint256 value) {
        need(c, n, code);
        for (uint256 i; i < n; ++i) {
            value = (value << 8) | uint8(c.data[c.pos++]);
        }
    }

    function slice(bytes memory b, uint256 start, uint256 n) private pure returns (bytes memory out) {
        out = new bytes(n);
        for (uint256 i; i < n; ++i) {
            out[i] = b[start + i];
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {BindingFold} from "./BindingFold.sol";
import {IndexKeys} from "./IndexKeys.sol";
import {StatePointReads} from "./StatePointReads.sol";
import {StateReadPrimitives} from "./StateReadPrimitives.sol";
import {StateStore} from "./StateStore.sol";
import {StorageByteView} from "./StorageByteView.sol";

library StateBindingReads {
    error ErrReadHistory(uint32 fromRevision, uint16 limit);

    struct BindingHistoryEntry {
        uint32 revision;
        uint64 admissionOrdinal;
        bytes32 envelopeId;
        uint16 leafIndex;
        uint8 occurrenceStatus;
        uint64 revokedAtOrdinal;
    }

    struct Cursor {
        bytes body;
        uint256 at;
    }

    struct ParsedMutation {
        uint8 kind;
        bytes32 purpose;
        bytes32 subject;
        bytes32 fieldRole;
        uint8 targetKind;
        bytes32 targetA;
        uint16 targetLeaf;
        bool predecessorPresent;
        bytes32 predecessorEnvelope;
        uint16 predecessorLeaf;
    }

    struct DecodedMutation {
        BindingFold.Head head;
        StatePointReads.HydratedOccurrence source;
    }

    struct ProbeBudget {
        uint8 used;
    }

    bytes32 private constant DOM_RECORD = keccak256("efs2/record/1");

    function getBindingHead(StateStore.Store storage s, bytes32 bindingKey)
        internal
        view
        returns (BindingFold.Head memory head, bytes32 realmBasis, uint64 highWaterOrdinal)
    {
        (realmBasis,, highWaterOrdinal) = StateReadPrimitives.basis(s, 0, bindingKey);
        head = _checkedCurrentHead(s, bindingKey, highWaterOrdinal);
    }

    function getBindingAtBasis(StateStore.Store storage s, bytes32 bindingKey, uint64 basisOrdinal)
        internal
        view
        returns (BindingFold.Head memory head, bytes32 realmBasis, uint64 highWaterOrdinal)
    {
        uint64 selectedH;
        (realmBasis, selectedH, highWaterOrdinal) = StateReadPrimitives.basis(s, basisOrdinal, bindingKey);
        BindingFold.Head memory current = _checkedCurrentHead(s, bindingKey, highWaterOrdinal);
        if (current.state == 0 || current.admissionOrdinal <= selectedH) return (current, realmBasis, selectedH);

        (bytes32 historyKey, StateReadPrimitives.PostingHead memory history) =
            _checkedHistoryHead(s, bindingKey, current, highWaterOrdinal);
        (uint64 end, uint64 ordinal) = _firstAfter(s, historyKey, history, selectedH, bindingKey);
        if (end == 0) return (head, realmBasis, selectedH);
        head = _decodeAt(s, bindingKey, historyKey, history, uint32(end), ordinal).head;
        return (head, realmBasis, selectedH);
    }

    function readHistory(StateStore.Store storage s, bytes32 bindingKey, uint32 fromRevision, uint16 limit)
        internal
        view
        returns (BindingHistoryEntry[] memory entries, uint32 nextRevision, uint8 completeness)
    {
        (,, uint64 currentH) = StateReadPrimitives.basis(s, 0, bindingKey);
        if (fromRevision == 0 || limit == 0 || limit > 64) revert ErrReadHistory(fromRevision, limit);
        BindingFold.Head memory current = _checkedCurrentHead(s, bindingKey, currentH);
        (bytes32 historyKey, StateReadPrimitives.PostingHead memory history) =
            _checkedHistoryHead(s, bindingKey, current, currentH);
        uint64 start = uint64(fromRevision) - 1;
        if (start >= history.count) return (new BindingHistoryEntry[](0), 0, 1);

        uint64 length = history.count - start;
        if (length > limit) length = limit;
        entries = new BindingHistoryEntry[](length);
        uint64 previous;
        if (start != 0) previous = StateReadPrimitives.postingAt(s, historyKey, history, start - 1, bindingKey);
        for (uint64 i; i < length; ++i) {
            uint64 position = start + i;
            uint64 ordinal = StateReadPrimitives.postingAt(s, historyKey, history, position, bindingKey);
            if (previous != 0 && ordinal <= previous) revert StorageByteView.ErrReadState(bindingKey);
            DecodedMutation memory decoded =
                _decodeAt(s, bindingKey, historyKey, history, uint32(position + 1), ordinal);
            entries[i] = BindingHistoryEntry(
                uint32(position + 1),
                ordinal,
                decoded.source.envelopeId,
                decoded.source.leafIndex,
                decoded.source.status,
                decoded.source.revokedAtOrdinal
            );
            previous = ordinal;
        }
        uint64 firstUnreturned = start + length;
        if (firstUnreturned == history.count) return (entries, 0, 1);
        uint64 following = StateReadPrimitives.postingAt(s, historyKey, history, firstUnreturned, bindingKey);
        if (following <= previous) revert StorageByteView.ErrReadState(bindingKey);
        nextRevision = uint32(firstUnreturned + 1);
        completeness = 2;
    }

    function _checkedCurrentHead(StateStore.Store storage s, bytes32 key, uint64 currentH)
        private
        view
        returns (BindingFold.Head memory head)
    {
        StateStore.BindingRow storage row = s.bindings[key];
        uint256 meta = row.meta;
        if (meta >> 120 != 0) revert StorageByteView.ErrReadState(key);
        head = BindingFold.unpack(meta, row.target);
        if (!BindingFold.validHead(head) || head.admissionOrdinal > currentH) {
            revert StorageByteView.ErrReadState(key);
        }
    }

    function _checkedHistoryHead(
        StateStore.Store storage s,
        bytes32 key,
        BindingFold.Head memory current,
        uint64 currentH
    ) private view returns (bytes32 historyKey, StateReadPrimitives.PostingHead memory history) {
        historyKey = IndexKeys.posting(0, 8, 0, key);
        history = StateReadPrimitives.postingHead(s, historyKey, true, currentH, key);
        if (current.state == 0) {
            if (history.count != 0) revert StorageByteView.ErrReadState(key);
            return (historyKey, history);
        }
        if (
            history.count != uint64(current.revision) || history.last != current.admissionOrdinal
                || history.count >= type(uint32).max
        ) revert StorageByteView.ErrReadState(key);
    }

    function _firstAfter(
        StateStore.Store storage s,
        bytes32 historyKey,
        StateReadPrimitives.PostingHead memory history,
        uint64 selectedH,
        bytes32 subject
    ) private view returns (uint64 end, uint64 selected) {
        uint64 lo;
        uint64 hi = history.count;
        ProbeBudget memory budget;
        while (lo < hi) {
            uint64 mid = lo + (hi - lo) / 2;
            uint64 value = _countedPostingAt(s, historyKey, history, mid, subject, budget);
            if (value <= selectedH) lo = mid + 1;
            else hi = mid;
        }
        end = lo;
        if (end != 0) {
            selected = _countedPostingAt(s, historyKey, history, end - 1, subject, budget);
            if (selected > selectedH) revert StorageByteView.ErrReadState(subject);
            if (end > 1) {
                uint64 previous = _countedPostingAt(s, historyKey, history, end - 2, subject, budget);
                if (previous >= selected) revert StorageByteView.ErrReadState(subject);
            }
        }
        if (end < history.count) {
            uint64 next = _countedPostingAt(s, historyKey, history, end, subject, budget);
            if (next <= selectedH || (selected != 0 && selected >= next)) {
                revert StorageByteView.ErrReadState(subject);
            }
            if (end + 1 < history.count) {
                uint64 following = _countedPostingAt(s, historyKey, history, end + 1, subject, budget);
                if (next >= following) revert StorageByteView.ErrReadState(subject);
            }
        }
    }

    function _countedPostingAt(
        StateStore.Store storage s,
        bytes32 historyKey,
        StateReadPrimitives.PostingHead memory history,
        uint64 position,
        bytes32 subject,
        ProbeBudget memory budget
    ) private view returns (uint64) {
        if (++budget.used > 48) revert StorageByteView.ErrReadState(subject);
        return StateReadPrimitives.postingAt(s, historyKey, history, position, subject);
    }

    function _decodeAt(
        StateStore.Store storage s,
        bytes32 key,
        bytes32 historyKey,
        StateReadPrimitives.PostingHead memory history,
        uint32 revision,
        uint64 ordinal
    ) private view returns (DecodedMutation memory result) {
        result.source = StatePointReads.hydrateOrdinal(s, ordinal, key);
        ParsedMutation memory mutation = _decodeBody(s, result.source, key);
        if (mutation.kind == 1 || mutation.kind == 2) {
            _validateDirect(s, key, historyKey, history, revision, ordinal, mutation, result.source.principalId);
            result.head = _directHead(mutation, revision, ordinal);
            return result;
        }
        if (mutation.kind != 3 || revision <= 1) revert StorageByteView.ErrReadState(key);

        uint64 targetOrdinal = StateReadPrimitives.postingAt(s, historyKey, history, uint64(revision) - 2, key);
        StatePointReads.HydratedOccurrence memory target = StatePointReads.hydrateOrdinal(s, targetOrdinal, key);
        if (
            mutation.targetA != target.envelopeId || mutation.targetLeaf != target.leafIndex
                || target.principalId != result.source.principalId || target.status != 2
                || target.revokedAtOrdinal != ordinal
        ) revert StorageByteView.ErrReadState(key);
        ParsedMutation memory targetMutation = _decodeBody(s, target, key);
        if (targetMutation.kind != 1 && targetMutation.kind != 2) revert StorageByteView.ErrReadState(key);
        _validateDirect(s, key, historyKey, history, revision - 1, targetOrdinal, targetMutation, target.principalId);
        result.head = BindingFold.Head(2, 0, 2, revision, ordinal, bytes32(0), 0);
    }

    function _validateDirect(
        StateStore.Store storage s,
        bytes32 key,
        bytes32 historyKey,
        StateReadPrimitives.PostingHead memory history,
        uint32 revision,
        uint64 ordinal,
        ParsedMutation memory mutation,
        bytes32 principal
    ) private view {
        bytes32 position = keccak256(
            abi.encode(keccak256("efs2/position/1"), mutation.purpose, mutation.subject, mutation.fieldRole)
        );
        bytes32 actualKey = keccak256(abi.encode(keccak256("efs2/binding/1"), principal, position));
        if (actualKey != key) revert StorageByteView.ErrReadState(key);
        if (revision == 1) {
            if (mutation.predecessorPresent) revert StorageByteView.ErrReadState(key);
            return;
        }
        if (!mutation.predecessorPresent || uint64(revision) > history.count) {
            revert StorageByteView.ErrReadState(key);
        }
        uint64 previousOrdinal = StateReadPrimitives.postingAt(s, historyKey, history, uint64(revision) - 2, key);
        if (previousOrdinal >= ordinal) revert StorageByteView.ErrReadState(key);
        StatePointReads.HydratedOccurrence memory previous = StatePointReads.hydrateOrdinal(s, previousOrdinal, key);
        if (mutation.predecessorEnvelope != previous.envelopeId || mutation.predecessorLeaf != previous.leafIndex) {
            revert StorageByteView.ErrReadState(key);
        }
    }

    function _directHead(ParsedMutation memory mutation, uint32 revision, uint64 ordinal)
        private
        pure
        returns (BindingFold.Head memory head)
    {
        if (mutation.kind == 1) {
            head = BindingFold.Head(1, mutation.targetKind, 0, revision, ordinal, mutation.targetA, mutation.targetLeaf);
        } else {
            head = BindingFold.Head(2, 0, 1, revision, ordinal, bytes32(0), 0);
        }
    }

    function _decodeBody(StateStore.Store storage s, StatePointReads.HydratedOccurrence memory occurrence, bytes32 key)
        private
        view
        returns (ParsedMutation memory mutation)
    {
        if (
            occurrence.typeSchemaId != s.init.bindingSetType && occurrence.typeSchemaId != s.init.bindingTombstoneType
                && occurrence.typeSchemaId != s.init.withdrawalType
        ) revert StorageByteView.ErrReadState(key);
        StateStore.RecordRow storage record = s.records[occurrence.recordId];
        uint256 length = record.body.length;
        if (length > 167) revert StorageByteView.ErrReadState(key);
        bytes memory body = StorageByteView.slice(record.body, 0, length, key);
        bytes32 actual = keccak256(abi.encode(DOM_RECORD, occurrence.typeSchemaId, keccak256(body)));
        if (actual != occurrence.recordId) revert StorageByteView.ErrReadState(key);
        Cursor memory cursor = Cursor(body, 0);
        if (occurrence.typeSchemaId == s.init.bindingSetType) {
            mutation.kind = 1;
            mutation.purpose = _word(cursor, key);
            mutation.subject = _word(cursor, key);
            mutation.fieldRole = _word(cursor, key);
            (bool recordPresent, bytes32 recordTarget) = _optionReference(cursor, key);
            (bool occurrencePresent, bytes32 occurrenceTarget, uint16 occurrenceLeaf) = _optionOccurrence(cursor, key);
            if (recordPresent == occurrencePresent) revert StorageByteView.ErrReadState(key);
            if (recordPresent) {
                mutation.targetKind = 1;
                mutation.targetA = recordTarget;
            } else {
                mutation.targetKind = 2;
                mutation.targetA = occurrenceTarget;
                mutation.targetLeaf = occurrenceLeaf;
            }
            (mutation.predecessorPresent, mutation.predecessorEnvelope, mutation.predecessorLeaf) =
                _optionOccurrence(cursor, key);
        } else if (occurrence.typeSchemaId == s.init.bindingTombstoneType) {
            mutation.kind = 2;
            mutation.purpose = _word(cursor, key);
            mutation.subject = _word(cursor, key);
            mutation.fieldRole = _word(cursor, key);
            (mutation.predecessorPresent, mutation.predecessorEnvelope, mutation.predecessorLeaf) =
                _optionOccurrence(cursor, key);
        } else if (occurrence.typeSchemaId == s.init.withdrawalType) {
            mutation.kind = 3;
            mutation.targetA = _referenceWord(cursor, key);
            mutation.targetLeaf = _short(cursor, key);
            if (mutation.targetLeaf >= 64) revert StorageByteView.ErrReadState(key);
        } else {
            revert StorageByteView.ErrReadState(key);
        }
        if (cursor.at != body.length) revert StorageByteView.ErrReadState(key);
    }

    function _optionReference(Cursor memory cursor, bytes32 subject)
        private
        pure
        returns (bool present, bytes32 value)
    {
        uint8 flag = _byte(cursor, subject);
        if (flag > 1) revert StorageByteView.ErrReadState(subject);
        present = flag == 1;
        if (present) value = _referenceWord(cursor, subject);
    }

    function _optionOccurrence(Cursor memory cursor, bytes32 subject)
        private
        pure
        returns (bool present, bytes32 envelopeId, uint16 leafIndex)
    {
        uint8 flag = _byte(cursor, subject);
        if (flag > 1) revert StorageByteView.ErrReadState(subject);
        present = flag == 1;
        if (present) {
            envelopeId = _referenceWord(cursor, subject);
            leafIndex = _short(cursor, subject);
            if (leafIndex >= 64) revert StorageByteView.ErrReadState(subject);
        }
    }

    function _referenceWord(Cursor memory cursor, bytes32 subject) private pure returns (bytes32 value) {
        value = _word(cursor, subject);
        if (uint256(value) < 65536) revert StorageByteView.ErrReadState(subject);
    }

    function _word(Cursor memory cursor, bytes32 subject) private pure returns (bytes32 value) {
        uint256 at = cursor.at;
        if (at > cursor.body.length || cursor.body.length - at < 32) revert StorageByteView.ErrReadState(subject);
        bytes memory body = cursor.body;
        assembly ("memory-safe") { value := mload(add(add(body, 32), at)) }
        cursor.at = at + 32;
    }

    function _short(Cursor memory cursor, bytes32 subject) private pure returns (uint16 value) {
        uint256 at = cursor.at;
        if (at > cursor.body.length || cursor.body.length - at < 2) revert StorageByteView.ErrReadState(subject);
        value = (uint16(uint8(cursor.body[at])) << 8) | uint16(uint8(cursor.body[at + 1]));
        cursor.at = at + 2;
    }

    function _byte(Cursor memory cursor, bytes32 subject) private pure returns (uint8 value) {
        if (cursor.at >= cursor.body.length) revert StorageByteView.ErrReadState(subject);
        value = uint8(cursor.body[cursor.at]);
        ++cursor.at;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {StateStore} from "./StateStore.sol";
import {Preparation} from "./Preparation.sol";
import {BindingFold} from "./BindingFold.sol";
import {IndexKeys} from "./IndexKeys.sol";

library StateKernel {
    struct EnvelopeHeader {
        uint16 profile;
        bytes32 principalId;
        bytes32 authorityRef;
        uint64 authEpoch;
        bytes32 pubNonce;
        uint64 notAfter;
    }

    struct SelectedLeaf {
        uint16 leafIndex;
        bytes32 typeId;
        bytes body;
    }

    struct ExpectedRevision {
        uint16 leafIndex;
        uint32 revision;
    }

    struct VerifiedContext {
        bytes32 authenticatedPrincipal;
        uint32 revisionOrdinal;
        uint256 authorityBasis;
        bytes32 authorityCodehash;
    }

    struct Publication {
        bytes32 envelopeId;
        EnvelopeHeader header;
        bytes32[] recordIds;
        uint64 leafMask;
        SelectedLeaf[] leaves;
        ExpectedRevision[] expectedRevisions;
    }

    struct LeafResult {
        uint16 leafIndex;
        uint8 outcome;
        uint64 admissionOrdinal;
    }

    struct AdmitResult {
        bytes32 envelopeId;
        uint64 envelopeOrdinal;
        uint64 acceptingBatchId;
        LeafResult[] leaves;
    }

    struct Init {
        bytes32 realmId;
        bytes32 initialRevisionId;
        bytes intrinsicGroupBytes;
        bytes objectGroup1Bytes;
        bytes kernelGroup2Bytes;
    }
    error ReferenceUnproved(uint16 leaf, uint8 role);
    error ReferenceClassUnsupported(uint16 leaf, uint8 role, uint8 targetClass);
    error AUTH_PRINCIPAL_MISMATCH(bytes32 declared, bytes32 computed);
    error E_REF_UNSATISFIED(uint16 leafIndex, uint8 roleOrdinal);
    error E_SELF_ENVELOPE_OCCREF(uint16 sourceLeafIndex, uint16 targetLeafIndex);
    error E_UNKNOWN_TYPE(uint16 leafIndex);
    error E_NO_RESURRECTION(bytes32 envelopeId, uint16 leafIndex);
    error E_BOUNDS(uint16 code);
    error E_TARGET_EVIDENCE(uint16 withdrawalLeafIndex);
    error ErrWithdrawNotAuthor(
        bytes32 targetEnvelopeId, uint16 targetLeafIndex, bytes32 envelopePrincipal, bytes32 targetPrincipal
    );
    error U48_GUARD();
    error InvalidInitialization();
    error InvalidCommitment();
    error InvalidRevision(uint32 revisionOrdinal);
    error InvalidCasCarriage();
    error MissingTypeDependency(bytes32 typeId);
    error CacheConflict(bytes32 typeId);
    uint64 private constant GUARD = (uint64(1) << 48) - 1;

    struct Plan {
        Preparation.Config config;
        StateStore.Change[] changes;
        uint256 length;
        StateStore.Counts count;
        StateStore.Bootstrap init;
        uint256[] slots;
    }

    function initialize(StateStore.Store storage s, Init memory init, Preparation.Config memory config) internal {
        if (
            s.init.realmId != 0 || init.realmId == 0 || init.initialRevisionId == 0
                || init.objectGroup1Bytes.length == 0 || init.kernelGroup2Bytes.length == 0
        ) revert InvalidInitialization();
        Preparation.CompiledType memory meta = Preparation.intrinsic(config, init.intrinsicGroupBytes);
        bytes32 gh = keccak256(abi.encode(keccak256("efs2/typeschema-group/1"), keccak256(init.intrinsicGroupBytes)));
        if (meta.typeId != keccak256(abi.encode(keccak256("efs2/typeschema/1"), gh, uint256(0)))) {
            revert InvalidCommitment();
        }
        s.init = StateStore.Bootstrap(
            init.realmId,
            init.initialRevisionId,
            init.intrinsicGroupBytes,
            keccak256(init.objectGroup1Bytes),
            keccak256(init.kernelGroup2Bytes),
            meta.typeId,
            0,
            0,
            0,
            0
        );
        s.types[meta.typeId] = StateStore.TypeRow(0, 0, 1, 0, meta.cacheBytes);
        s.typeIds[1] = meta.typeId;
        s.count.types = 1;
    }

    function admit(
        StateStore.Store storage s,
        VerifiedContext memory v,
        Publication memory p,
        Preparation.Config memory config
    ) internal returns (AdmitResult memory r) {
        return admitAtRevision(s, v, p, config, 1);
    }

    /// @notice Explicit host-checked revision seam; legacy admission stays revision one.
    function admitAtRevision(
        StateStore.Store storage s,
        VerifiedContext memory v,
        Publication memory p,
        Preparation.Config memory config,
        uint32 activeRevision
    ) internal returns (AdmitResult memory r) {
        if (s.init.realmId == 0) revert InvalidInitialization();
        if (p.header.principalId != v.authenticatedPrincipal) {
            revert AUTH_PRINCIPAL_MISMATCH(p.header.principalId, v.authenticatedPrincipal);
        }
        if (activeRevision == 0 || v.revisionOrdinal != activeRevision) revert InvalidRevision(v.revisionOrdinal);
        carriage(p);
        r.envelopeId = p.envelopeId;
        r.envelopeOrdinal = s.envelopes[p.envelopeId].envelopeOrdinal;
        r.leaves = new LeafResult[](p.leaves.length);
        uint256 fresh;
        for (uint256 i; i < p.leaves.length; ++i) {
            SelectedLeaf memory leaf = p.leaves[i];
            uint256 packedStatus = s.occurrences[occKey(p.envelopeId, leaf.leafIndex)].packed;
            // Lifecycle packing fixes status in the low byte and the admission
            // ordinal in the next 48 bits; the remaining bits are reserved.
            // forge-lint: disable-next-line(unsafe-typecast)
            uint8 status = uint8(packedStatus);
            if (status > 1) revert E_NO_RESURRECTION(p.envelopeId, leaf.leafIndex);
            // GUARD masks the shifted value to the declared u48 ordinal range.
            // forge-lint: disable-next-line(unsafe-typecast)
            uint64 ord = uint64((packedStatus >> 8) & GUARD);
            r.leaves[i] = LeafResult(leaf.leafIndex, status == 1 ? 2 : 1, ord);
            if (status == 0) ++fresh;
        }
        Plan memory plan;
        plan.config = config;
        plan.count = s.count;
        plan.init = s.init;
        // ACTIVE leaves stage nothing. Each fresh leaf has a conservative
        // 256-change allowance; Envelope/Principal pairs and Batch add five.
        allocateJournal(plan, fresh == 0 ? 0 : fresh * 256 + 5);
        if (fresh == 0) {
            for (uint256 i; i < p.leaves.length; ++i) {
                checked(
                    s, plan, p.leaves[i], p.envelopeId, p.recordIds[p.leaves[i].leafIndex], p.header.principalId, true
                );
            }
            return r;
        }
        if (fresh >= GUARD - plan.count.admissions || block.number >= GUARD) revert U48_GUARD();
        r.acceptingBatchId = next(plan.count.batches);
        plan.count.batches = r.acceptingBatchId;
        if (r.envelopeOrdinal == 0) {
            r.envelopeOrdinal = next(plan.count.envelopes);
            plan.count.envelopes = r.envelopeOrdinal;
            put(
                s,
                plan,
                StateStore.Kind.Envelope,
                p.envelopeId,
                0,
                abi.encode(StateStore.EnvelopeRow(abi.encode(p.header, p.recordIds), r.envelopeOrdinal))
            );
            put(s, plan, StateStore.Kind.EnvelopeId, 0, r.envelopeOrdinal, abi.encode(p.envelopeId));
        }
        StateStore.PrincipalRow memory pr =
            abi.decode(get(s, plan, StateStore.Kind.Principal, p.header.principalId, 0), (StateStore.PrincipalRow));
        if (pr.principalOrdinal == 0) {
            pr = StateStore.PrincipalRow(next(plan.count.principals), plan.count.admissions + 1);
            plan.count.principals = pr.principalOrdinal;
            put(s, plan, StateStore.Kind.Principal, p.header.principalId, 0, abi.encode(pr));
            put(s, plan, StateStore.Kind.PrincipalId, 0, pr.principalOrdinal, abi.encode(p.header.principalId));
        }
        uint64 first = plan.count.admissions + 1;
        uint256 casIndex;
        for (uint256 i; i < p.leaves.length; ++i) {
            casIndex = planLeaf(s, plan, p, r.leaves[i], i, pr.principalOrdinal, casIndex);
        }
        if (casIndex != p.expectedRevisions.length) revert InvalidCasCarriage();
        put(
            s,
            plan,
            StateStore.Kind.Batch,
            0,
            r.acceptingBatchId,
            abi.encode(
                StateStore.BatchRow(
                    uint256(first) | (fresh << 48) | (block.number << 64) | (uint256(v.revisionOrdinal) << 112),
                    v.authorityBasis,
                    v.authorityCodehash
                )
            )
        );
        // No semantic decisions below this boundary. All journal prestates are
        // checked against storage immediately before the recorded write.
        bytes32 countBefore = keccak256(abi.encode(s.count));
        bytes32 initBefore = keccak256(abi.encode(s.init));
        for (uint256 i; i < plan.length; ++i) {
            StateStore.replay(s, plan.changes[i]);
        }
        assert(countBefore == keccak256(abi.encode(s.count)) && initBefore == keccak256(abi.encode(s.init)));
        s.count = plan.count;
        s.init = plan.init;
    }

    function planLeaf(
        StateStore.Store storage s,
        Plan memory plan,
        Publication memory p,
        LeafResult memory result,
        uint256 i,
        uint64 principalOrdinal,
        uint256 casIndex
    ) private view returns (uint256) {
        SelectedLeaf memory leaf = p.leaves[i];
        Preparation.PreparedRecord memory prepared =
            checked(s, plan, leaf, p.envelopeId, p.recordIds[leaf.leafIndex], p.header.principalId, false);
        BindingFold.Effect memory effect = prepared.effect;
        uint32 expected;
        if (effect.kind == 1 || effect.kind == 2) {
            if (casIndex >= p.expectedRevisions.length || p.expectedRevisions[casIndex].leafIndex != leaf.leafIndex) {
                revert InvalidCasCarriage();
            }
            expected = p.expectedRevisions[casIndex++].revision;
        }
        if (result.outcome == 2) return casIndex;
        references(s, plan, prepared.references, leaf.leafIndex);
        uint64 ord = next(plan.count.admissions);
        plan.count.admissions = ord;
        result.admissionOrdinal = ord;
        bytes32 recordId = p.recordIds[leaf.leafIndex];
        {
            StateStore.RecordRow memory rr =
                abi.decode(get(s, plan, StateStore.Kind.Record, recordId, 0), (StateStore.RecordRow));
            if (rr.recordOrdinal == 0) {
                rr = StateStore.RecordRow(leaf.typeId, leaf.body, next(plan.count.records), ord);
                plan.count.records = rr.recordOrdinal;
                put(s, plan, StateStore.Kind.Record, recordId, 0, abi.encode(rr));
                put(s, plan, StateStore.Kind.RecordId, 0, rr.recordOrdinal, abi.encode(recordId));
            }
        }
        if (leaf.typeId == plan.init.metaTypeId) group(s, plan, leaf.body, recordId, ord);
        StateStore.TypeRow memory tr =
            abi.decode(get(s, plan, StateStore.Kind.Type, leaf.typeId, 0), (StateStore.TypeRow));
        put(
            s,
            plan,
            StateStore.Kind.Admission,
            0,
            ord,
            abi.encode(
                StateStore.AdmissionRow(
                    p.envelopeId,
                    uint256(leaf.leafIndex) | (uint256(tr.typeOrdinal) << 16) | (uint256(principalOrdinal) << 64)
                )
            )
        );
        put(
            s,
            plan,
            StateStore.Kind.Lifecycle,
            occKey(p.envelopeId, leaf.leafIndex),
            0,
            abi.encode(StateStore.LifecycleRow(1 | (uint256(ord) << 8)))
        );
        occurrencePostings(s, plan, leaf.typeId, prepared.occurrenceKeys, ord, true);
        if (effect.kind == 1 || effect.kind == 2) bindingEffect(s, plan, effect, p.header.principalId, expected, ord);
        else if (effect.kind == 3) withdrawal(s, plan, effect, p.header.principalId, leaf.leafIndex, ord);
        return casIndex;
    }

    function carriage(Publication memory p) private pure {
        uint256 n = p.recordIds.length;
        if (
            n == 0 || n > 64 || p.leaves.length == 0 || p.leaves.length > 64 || p.expectedRevisions.length > 64
                || (n < 64 && p.leafMask >> n != 0)
        ) revert E_BOUNDS(1);
        uint64 mask;
        uint256 total;
        for (uint256 i; i < p.leaves.length; ++i) {
            SelectedLeaf memory leaf = p.leaves[i];
            if (leaf.leafIndex >= n || (i != 0 && leaf.leafIndex <= p.leaves[i - 1].leafIndex)) revert E_BOUNDS(2);
            mask |= uint64(1) << leaf.leafIndex;
            total += leaf.body.length;
            if (leaf.body.length > 8192 || total > 8192) revert E_BOUNDS(3);
            if (
                p.recordIds[leaf.leafIndex]
                    != keccak256(abi.encode(keccak256("efs2/record/1"), leaf.typeId, keccak256(leaf.body)))
            ) revert InvalidCommitment();
        }
        if (mask != p.leafMask) revert E_BOUNDS(2);
        bytes32 domain = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version)"), keccak256("EFS2-Envelope"), keccak256("1")
            )
        );
        bytes32 statement = keccak256(
            abi.encode(
                keccak256(
                    "PublicationEnvelope(uint16 profile,bytes32 principalId,bytes32 authorityRef,uint64 authEpoch,bytes32 pubNonce,uint64 notAfter,bytes32[] recordIds)"
                ),
                p.header,
                keccak256(abi.encodePacked(p.recordIds))
            )
        );
        if (
            p.envelopeId
                != keccak256(
                    abi.encode(keccak256("efs2/envelope/1"), keccak256(abi.encodePacked(hex"1901", domain, statement)))
                )
        ) revert InvalidCommitment();
    }

    function checked(
        StateStore.Store storage s,
        Plan memory p,
        SelectedLeaf memory leaf,
        bytes32 envelopeId,
        bytes32 recordId,
        bytes32 principal,
        bool bodyOnly
    ) private view returns (Preparation.PreparedRecord memory prepared) {
        StateStore.TypeRow memory tr = abi.decode(get(s, p, StateStore.Kind.Type, leaf.typeId, 0), (StateStore.TypeRow));
        if (tr.typeOrdinal == 0) revert E_UNKNOWN_TYPE(leaf.leafIndex);
        prepared =
            Preparation.record(p.config, tr.cacheBytes, leaf.typeId, leaf.body, recordId, principal, ids(p), bodyOnly);
        for (uint256 j; j < prepared.references.length; ++j) {
            if (prepared.references[j].targetClass == 4 && prepared.references[j].targetId == envelopeId) {
                revert E_SELF_ENVELOPE_OCCREF(leaf.leafIndex, prepared.references[j].leafIndex);
            }
        }
    }

    function references(StateStore.Store storage s, Plan memory p, Preparation.PreparedRef[] memory refs, uint16 leaf)
        private
        view
    {
        for (uint256 i; i < refs.length; ++i) {
            Preparation.PreparedRef memory ref = refs[i];
            if (ref.targetClass == 1 || ref.targetClass == 5) {
                StateStore.RecordRow memory target =
                    abi.decode(get(s, p, StateStore.Kind.Record, ref.targetId, 0), (StateStore.RecordRow));
                if (target.recordOrdinal == 0) revert ReferenceUnproved(leaf, ref.roleIndex);
                if (
                    (ref.targetClass == 5
                            && (p.init.objectGenesisType == 0 || target.typeId != p.init.objectGenesisType))
                        || (ref.expectedType != 0 && ref.expectedType != target.typeId)
                ) revert E_REF_UNSATISFIED(leaf, ref.roleIndex);
            } else if (ref.targetClass == 4) {
                bytes memory raw = s.envelopes[ref.targetId].canonicalUnsignedEnvelope;
                if (raw.length == 0) revert ReferenceUnproved(leaf, ref.roleIndex);
                (, bytes32[] memory vector) = abi.decode(raw, (EnvelopeHeader, bytes32[]));
                if (ref.leafIndex >= vector.length) revert E_REF_UNSATISFIED(leaf, ref.roleIndex);
            } else {
                revert ReferenceClassUnsupported(leaf, ref.roleIndex, ref.targetClass);
            }
        }
    }

    function group(StateStore.Store storage s, Plan memory p, bytes memory body, bytes32 recordId, uint64 ord)
        private
        view
    {
        bytes memory raw = new bytes(body.length - 2);
        for (uint256 i; i < raw.length; ++i) {
            raw[i] = body[i + 2];
        }
        Preparation.CompiledGroup memory compiled = Preparation.group(p.config, raw);
        bytes32 hash = keccak256(raw);
        bytes32 gh = keccak256(abi.encode(keccak256("efs2/typeschema-group/1"), hash));
        if (compiled.groupHash != gh || compiled.rawHash != hash) revert InvalidCommitment();
        Preparation.CompiledType[] memory ss = compiled.types;
        bytes32[] memory deps = compiled.dependencies;
        for (uint256 i; i < deps.length; ++i) {
            if (abi.decode(get(s, p, StateStore.Kind.Type, deps[i], 0), (StateStore.TypeRow)).typeOrdinal == 0) {
                revert MissingTypeDependency(deps[i]);
            }
        }
        for (uint256 i; i < ss.length; ++i) {
            if (ss[i].typeId != keccak256(abi.encode(keccak256("efs2/typeschema/1"), gh, i))) {
                revert InvalidCommitment();
            }
            StateStore.TypeRow memory row =
                abi.decode(get(s, p, StateStore.Kind.Type, ss[i].typeId, 0), (StateStore.TypeRow));
            bytes memory cache = ss[i].cacheBytes;
            if (row.typeOrdinal != 0) {
                if (
                    row.groupRecordId != recordId || row.memberIndex != i
                        || keccak256(row.cacheBytes) != keccak256(cache)
                ) {
                    revert CacheConflict(ss[i].typeId);
                }
            } else {
                row = StateStore.TypeRow(recordId, uint16(i), next(p.count.types), ord, cache);
                p.count.types = row.typeOrdinal;
                put(s, p, StateStore.Kind.Type, ss[i].typeId, 0, abi.encode(row));
                put(s, p, StateStore.Kind.TypeId, 0, row.typeOrdinal, abi.encode(ss[i].typeId));
            }
        }
        if (hash == p.init.objectGroup1Hash) {
            if (ss.length != 6) revert InvalidInitialization();
            p.init.objectGenesisType = ss[0].typeId;
        }
        if (hash == p.init.kernelGroup2Hash) {
            if (ss.length != 3) revert InvalidInitialization();
            p.init.bindingSetType = ss[0].typeId;
            p.init.bindingTombstoneType = ss[1].typeId;
            p.init.withdrawalType = ss[2].typeId;
        }
    }

    function occurrencePostings(
        StateStore.Store storage s,
        Plan memory p,
        bytes32 typeId,
        bytes32[] memory keys,
        uint64 ord,
        bool add
    ) private view {
        uint256 beforeHead = head(s, p, keys[0]);
        uint64 live = uint64(beforeHead >> 64);
        for (uint256 i; i < keys.length; ++i) {
            if (add) append(s, p, keys[i], ord, false);
            else liveDelta(s, p, keys[i], false);
        }
        bytes32 unique = IndexKeys.posting(typeId, 2, 0, 0);
        if (add && live == 0) {
            if (uint64(beforeHead) == 0) {
                append(s, p, unique, ord, false);
            } else {
                liveDelta(s, p, unique, true);
            }
        }
        if (!add && live == 1) liveDelta(s, p, unique, false);
    }

    function bindingEffect(
        StateStore.Store storage s,
        Plan memory p,
        BindingFold.Effect memory effect,
        bytes32 principal,
        uint32 expected,
        uint64 ord
    ) private view {
        bytes32 key = BindingFold.bindingKey(principal, BindingFold.positionKey(effect));
        StateStore.BindingRow memory row =
            abi.decode(get(s, p, StateStore.Kind.Binding, key, 0), (StateStore.BindingRow));
        BindingFold.Head memory beforeHead = BindingFold.unpack(row.meta, row.target);
        BindingFold.OccurrenceRef memory source;
        if (beforeHead.admissionOrdinal != 0) {
            StateStore.AdmissionRow memory old = abi.decode(
                get(s, p, StateStore.Kind.Admission, 0, beforeHead.admissionOrdinal), (StateStore.AdmissionRow)
            );
            source = BindingFold.OccurrenceRef(old.envelopeId, uint16(old.packed));
        }
        BindingFold.Head memory afterHead = BindingFold.advance(key, beforeHead, source, effect, expected, ord);
        if (beforeHead.state == 0) {
            p.count.bindingKeys = next(p.count.bindingKeys);
            put(s, p, StateStore.Kind.BindingKey, 0, p.count.bindingKeys, abi.encode(key));
            append(
                s, p, IndexKeys.posting(0, 10, 0, IndexKeys.scope(principal, effect.purpose, effect.subject)), ord, true
            );
        }
        saveBinding(s, p, key, afterHead, ord);
    }

    function saveBinding(StateStore.Store storage s, Plan memory p, bytes32 key, BindingFold.Head memory h, uint64 ord)
        private
        view
    {
        (uint256 meta, bytes32 target) = BindingFold.pack(h);
        put(s, p, StateStore.Kind.Binding, key, 0, abi.encode(StateStore.BindingRow(meta, target)));
        append(s, p, IndexKeys.posting(0, 8, 0, key), ord, true);
    }

    function withdrawal(
        StateStore.Store storage s,
        Plan memory p,
        BindingFold.Effect memory e,
        bytes32 author,
        uint16 sourceLeaf,
        uint64 ord
    ) private view {
        bytes32 key = occKey(e.targetA, e.targetLeaf);
        uint256 life = abi.decode(get(s, p, StateStore.Kind.Lifecycle, key, 0), (StateStore.LifecycleRow)).packed;
        if (uint8(life) == 0 || uint8(life) == 3) revert E_TARGET_EVIDENCE(sourceLeaf);
        (EnvelopeHeader memory eh, bytes32[] memory vector) =
            abi.decode(s.envelopes[e.targetA].canonicalUnsignedEnvelope, (EnvelopeHeader, bytes32[]));
        if (eh.principalId != author) revert ErrWithdrawNotAuthor(e.targetA, e.targetLeaf, author, eh.principalId);
        StateStore.RecordRow memory rr = s.records[vector[e.targetLeaf]];
        if (rr.typeId == p.init.withdrawalType) revert E_TARGET_EVIDENCE(sourceLeaf);
        if (uint8(life) == 2) return;
        uint64 targetOrd = uint64((life >> 8) & GUARD);
        Preparation.PreparedRecord memory prepared = Preparation.record(
            p.config,
            s.types[rr.typeId].cacheBytes,
            rr.typeId,
            rr.body,
            vector[e.targetLeaf],
            eh.principalId,
            ids(p),
            false
        );
        put(
            s,
            p,
            StateStore.Kind.Lifecycle,
            key,
            0,
            abi.encode(StateStore.LifecycleRow(2 | (uint256(targetOrd) << 8) | (uint256(ord) << 56)))
        );
        occurrencePostings(s, p, rr.typeId, prepared.occurrenceKeys, ord, false);
        BindingFold.Effect memory old = prepared.effect;
        if (old.kind == 1 || old.kind == 2) {
            bytes32 bindingKey = BindingFold.bindingKey(author, BindingFold.positionKey(old));
            StateStore.BindingRow memory br =
                abi.decode(get(s, p, StateStore.Kind.Binding, bindingKey, 0), (StateStore.BindingRow));
            BindingFold.Head memory bh = BindingFold.unpack(br.meta, br.target);
            if (bh.admissionOrdinal == targetOrd) {
                saveBinding(s, p, bindingKey, BindingFold.withdrawHead(bindingKey, bh, ord), ord);
            }
        }
    }

    function head(StateStore.Store storage s, Plan memory p, bytes32 key) private view returns (uint256) {
        return abi.decode(get(s, p, StateStore.Kind.Posting, key, 0), (StateStore.PostingRow)).head;
    }

    function append(StateStore.Store storage s, Plan memory p, bytes32 key, uint64 ord, bool audit) private view {
        uint256 beforeHead = head(s, p, key);
        uint64 count = uint64(beforeHead);
        uint64 live = uint64(beforeHead >> 64);
        uint64 last = uint64((beforeHead >> 128) & GUARD);
        uint16 flags = uint16(beforeHead >> 176);
        assert(ord > last && (count == 0 || flags == (audit ? 1 : 0)));
        if (count >= GUARD - 1 || live >= GUARD - 1) revert U48_GUARD();
        if (count == 0) {
            p.count.postingKeys = next(p.count.postingKeys);
            put(s, p, StateStore.Kind.PostingKey, 0, p.count.postingKeys, abi.encode(key));
        }
        uint64 wordIndex = count / 5;
        uint256 word = abi.decode(get(s, p, StateStore.Kind.Word, key, wordIndex), (uint256));
        uint256 shift = 48 * (count % 5);
        assert((word >> shift) == 0);
        put(s, p, StateStore.Kind.Word, key, wordIndex, abi.encode(word | (uint256(ord) << shift)));
        put(
            s,
            p,
            StateStore.Kind.Posting,
            key,
            0,
            abi.encode(
                StateStore.PostingRow(
                    uint256(count + 1) | (uint256(live + 1) << 64) | (uint256(ord) << 128)
                        | (uint256(audit ? 1 : 0) << 176)
                )
            )
        );
    }

    function liveDelta(StateStore.Store storage s, Plan memory p, bytes32 key, bool increase) private view {
        uint256 h = head(s, p, key);
        uint64 live = uint64(h >> 64);
        assert(uint16(h >> 176) == 0);
        if (increase) {
            if (live >= GUARD - 1) revert U48_GUARD();
            ++live;
        } else {
            assert(live > 0);
            --live;
        }
        put(
            s,
            p,
            StateStore.Kind.Posting,
            key,
            0,
            abi.encode(StateStore.PostingRow((h & ~(uint256(type(uint64).max) << 64)) | (uint256(live) << 64)))
        );
    }

    // Memory-only index; persisted rows and journal replay ordering are unchanged.
    // Admission bounds capacity to 64 * 256 + 5, so the table is at most 65536.
    function allocateJournal(Plan memory p, uint256 capacity) internal pure {
        p.changes = new StateStore.Change[](capacity);
        if (capacity == 0) return;
        uint256 size = 1;
        while (size < capacity * 2) size <<= 1;
        p.slots = new uint256[](size);
    }

    function journalSlot(Plan memory p, StateStore.Kind kind, bytes32 key, uint64 index)
        private
        pure
        returns (uint256 slot)
    {
        uint256 size = p.slots.length;
        // Three canonical ABI words in temporary free memory. Do not advance
        // the allocator or overwrite Solidity's zero slot; no value escapes.
        bytes32 hash;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, and(kind, 0xff))
            mstore(add(ptr, 0x20), key)
            mstore(add(ptr, 0x40), and(index, 0xffffffffffffffff))
            hash := keccak256(ptr, 0x60)
        }
        slot = uint256(hash) & (size - 1);
        for (uint256 probes; probes < size; ++probes) {
            uint256 row = p.slots[slot];
            if (row == 0) return slot;
            StateStore.Change memory c = p.changes[row - 1];
            if (c.kind == kind && c.key == key && c.index == index) return slot;
            slot = (slot + 1) & (size - 1);
        }
        assert(false);
    }

    function get(StateStore.Store storage s, Plan memory p, StateStore.Kind kind, bytes32 key, uint64 index)
        internal
        view
        returns (bytes memory value)
    {
        (value,) = journalRead(s, p, kind, key, index);
    }

    function journalRead(StateStore.Store storage s, Plan memory p, StateStore.Kind kind, bytes32 key, uint64 index)
        private
        view
        returns (bytes memory value, uint256 slot)
    {
        if (p.slots.length != 0) {
            slot = journalSlot(p, kind, key, index);
            uint256 row = p.slots[slot];
            if (row != 0) return (p.changes[row - 1].afterValue, slot);
        }
        return (StateStore.read(s, kind, key, index), slot);
    }

    function put(
        StateStore.Store storage s,
        Plan memory p,
        StateStore.Kind kind,
        bytes32 key,
        uint64 index,
        bytes memory value
    ) internal view {
        assert(p.length < p.changes.length);
        (bytes memory beforeValue, uint256 slot) = journalRead(s, p, kind, key, index);
        p.changes[p.length++] = StateStore.Change(kind, key, index, beforeValue, value);
        p.slots[slot] = p.length;
    }

    function next(uint64 n) private pure returns (uint64) {
        if (n >= GUARD - 1) revert U48_GUARD();
        return n + 1;
    }

    function occKey(bytes32 envelopeId, uint16 leaf) internal pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("efs2/occurrence/1"), envelopeId, uint256(leaf)));
    }

    function ids(Plan memory p) private pure returns (BindingFold.KernelIds memory) {
        return BindingFold.KernelIds(p.init.bindingSetType, p.init.bindingTombstoneType, p.init.withdrawalType);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {StateStore} from "./StateStore.sol";
import {StateKernel} from "./StateKernel.sol";
import {StorageByteView} from "./StorageByteView.sol";

library StatePointReads {
    uint256 private constant ORDINAL_MAX = (uint256(1) << 48) - 1;
    uint256 private constant CACHE_MAX = 131072;

    error ErrReadOrdinal(uint64 ordinal);

    struct IndexedReceiptView {
        bytes32 envelopeId;
        uint16 leafIndex;
        bytes32 realmId;
        bytes32 realmRevisionId;
        uint256 authorityBasis;
        bytes32 authorityCodehash;
        uint64 authEpoch;
        uint64 admissionOrdinal;
        uint48 admittedAtBlock;
        uint8 acceptedStatus;
        uint8 occurrenceStatus;
        uint64 revokedAtOrdinal;
    }

    struct EnvelopeMetadata {
        uint64 ordinal;
        uint16 leafCount;
        bytes32 principalId;
        uint64 authEpoch;
        uint256 byteLength;
    }

    struct HydratedOccurrence {
        bytes32 envelopeId;
        uint16 leafIndex;
        bytes32 recordId;
        bytes32 typeSchemaId;
        bytes32 principalId;
        uint8 status;
        uint64 ordinal;
        uint64 revokedAtOrdinal;
    }

    struct BatchMetadata {
        uint64 first;
        uint16 count;
        uint48 admittedAtBlock;
        uint256 authorityBasis;
        bytes32 authorityCodehash;
    }

    struct ProbeBudget {
        uint8 used;
    }

    function getOccurrence(StateStore.Store storage s, bytes32 envelopeId, uint16 leafIndex)
        internal
        view
        returns (
            uint8 status,
            uint64 ordinal,
            bytes32 recordId,
            bytes32 typeSchemaId,
            bytes32 principalId,
            uint64 revokedAtOrdinal
        )
    {
        _requireOccurrenceCounters(s, envelopeId);
        uint256 lifecycle = s.occurrences[StateKernel.occKey(envelopeId, leafIndex)].packed;
        if (lifecycle == 0) return (0, 0, 0, 0, 0, 0);
        (HydratedOccurrence memory occurrence,) = _hydrate(s, envelopeId, leafIndex, 0, lifecycle, envelopeId);
        return (
            occurrence.status,
            occurrence.ordinal,
            occurrence.recordId,
            occurrence.typeSchemaId,
            occurrence.principalId,
            occurrence.revokedAtOrdinal
        );
    }

    function getOccurrenceByOrdinal(StateStore.Store storage s, uint64 ordinal)
        internal
        view
        returns (
            bytes32 envelopeId,
            uint16 leafIndex,
            bytes32 recordId,
            bytes32 typeSchemaId,
            bytes32 principalId,
            uint8 status,
            uint64 revokedAtOrdinal
        )
    {
        bytes32 subject = bytes32(uint256(ordinal));
        uint64 currentH = requireState(s, subject);
        _requireRequestedOrdinal(ordinal, currentH);
        HydratedOccurrence memory occurrence = _hydrateOrdinalChecked(s, ordinal, subject);
        return (
            occurrence.envelopeId,
            occurrence.leafIndex,
            occurrence.recordId,
            occurrence.typeSchemaId,
            occurrence.principalId,
            occurrence.status,
            occurrence.revokedAtOrdinal
        );
    }

    function requireState(StateStore.Store storage s, bytes32 subject) internal view returns (uint64 currentH) {
        _requireOccurrenceCounters(s, subject);
        currentH = s.count.admissions;
    }

    function hydrateOrdinal(StateStore.Store storage s, uint64 ordinal, bytes32 subject)
        internal
        view
        returns (HydratedOccurrence memory)
    {
        uint64 currentH = requireState(s, subject);
        if (ordinal == 0 || ordinal >= ORDINAL_MAX || ordinal > currentH) {
            revert StorageByteView.ErrReadState(subject);
        }
        return _hydrateOrdinalChecked(s, ordinal, subject);
    }

    function _hydrateOrdinalChecked(StateStore.Store storage s, uint64 ordinal, bytes32 subject)
        private
        view
        returns (HydratedOccurrence memory occurrence)
    {
        StateStore.AdmissionRow storage admission = s.admissions[ordinal];
        uint256 packed = admission.packed;
        if (admission.envelopeId == 0 || packed >> 112 != 0) revert StorageByteView.ErrReadState(subject);
        // The remaining high bits were validated before selecting the low leaf field.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 leafIndex = uint16(packed);
        (occurrence,) = _hydrate(
            s,
            admission.envelopeId,
            leafIndex,
            ordinal,
            s.occurrences[StateKernel.occKey(admission.envelopeId, leafIndex)].packed,
            subject
        );
    }

    function getReceipt(StateStore.Store storage s, uint64 ordinal) internal view returns (IndexedReceiptView memory) {
        bytes32 subject = bytes32(uint256(ordinal));
        _requireOccurrenceCounters(s, subject);
        _requireRequestedOrdinal(ordinal, s.count.admissions);
        if (s.init.initialRevisionId == 0) revert StorageByteView.ErrReadState(subject);
        StateStore.AdmissionRow storage admission = s.admissions[ordinal];
        uint256 packed = admission.packed;
        if (admission.envelopeId == 0 || packed >> 112 != 0) revert StorageByteView.ErrReadState(subject);
        // The remaining high bits were validated before selecting the low leaf field.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 leafIndex = uint16(packed);
        (HydratedOccurrence memory occurrence, uint64 authEpoch) = _hydrate(
            s,
            admission.envelopeId,
            leafIndex,
            ordinal,
            s.occurrences[StateKernel.occKey(admission.envelopeId, leafIndex)].packed,
            subject
        );
        BatchMetadata memory batch = _acceptingBatch(s, ordinal, subject);
        return IndexedReceiptView(
            occurrence.envelopeId,
            occurrence.leafIndex,
            s.init.realmId,
            s.init.initialRevisionId,
            batch.authorityBasis,
            batch.authorityCodehash,
            authEpoch,
            occurrence.ordinal,
            batch.admittedAtBlock,
            1,
            occurrence.status,
            occurrence.revokedAtOrdinal
        );
    }

    function getTypeSchema(StateStore.Store storage s, bytes32 typeId)
        internal
        view
        returns (
            bytes memory canonicalBody,
            uint48 typeOrd,
            uint64 admitOrdinal,
            uint8 refRoleCount,
            uint8 indexSpecCount
        )
    {
        _requireInitialized(s, typeId);
        StateStore.TypeRow storage row = s.types[typeId];
        if (row.typeOrdinal == 0) {
            if (
                row.groupRecordId != 0 || row.memberIndex != 0 || row.admittedAtOrdinal != 0
                    || row.cacheBytes.length != 0
            ) {
                revert StorageByteView.ErrReadState(typeId);
            }
            return (new bytes(0), 0, 0, 0, 0);
        }
        _validOrdinal(row.typeOrdinal, s.count.types, typeId);
        if (typeId == s.init.metaTypeId) {
            if (row.typeOrdinal != 1 || row.admittedAtOrdinal != 0 || row.groupRecordId != 0 || row.memberIndex != 0) {
                revert StorageByteView.ErrReadState(typeId);
            }
            canonicalBody = _intrinsicBlob(s, typeId);
        } else {
            (uint256 start, uint256 length) = _ordinaryMemberRange(s, row, typeId);
            canonicalBody = StorageByteView.slice(s.records[row.groupRecordId].body, start, length, typeId);
        }
        (refRoleCount, indexSpecCount) = _cacheCounts(row.cacheBytes, typeId, canonicalBody);
        // The ordinal was checked against the u48 exhaustion boundary before narrowing.
        // forge-lint: disable-next-line(unsafe-typecast)
        typeOrd = uint48(row.typeOrdinal);
        return (canonicalBody, typeOrd, row.admittedAtOrdinal, refRoleCount, indexSpecCount);
    }

    function getTypeOrigin(StateStore.Store storage s, bytes32 typeId)
        internal
        view
        returns (bytes32 groupRecordId, uint16 memberIndex, bool intrinsic)
    {
        _requireInitialized(s, typeId);
        StateStore.TypeRow storage row = s.types[typeId];
        if (row.typeOrdinal == 0) {
            if (row.groupRecordId != 0 || row.memberIndex != 0 || row.admittedAtOrdinal != 0) {
                revert StorageByteView.ErrReadState(typeId);
            }
            return (0, 0, false);
        }
        _validOrdinal(row.typeOrdinal, s.count.types, typeId);
        if (typeId == s.init.metaTypeId) {
            if (row.typeOrdinal != 1 || row.admittedAtOrdinal != 0 || row.groupRecordId != 0 || row.memberIndex != 0) {
                revert StorageByteView.ErrReadState(typeId);
            }
            return (0, 0, true);
        }
        _ordinaryMemberRange(s, row, typeId);
        return (row.groupRecordId, row.memberIndex, false);
    }

    function intrinsicTypeGroupBytes(StateStore.Store storage s) internal view returns (bytes memory) {
        _requireInitialized(s, s.init.metaTypeId);
        bytes32 subject = s.init.metaTypeId;
        StateStore.TypeRow storage row = s.types[subject];
        _validOrdinal(row.typeOrdinal, s.count.types, subject);
        if (row.typeOrdinal != 1 || row.admittedAtOrdinal != 0 || row.groupRecordId != 0 || row.memberIndex != 0) {
            revert StorageByteView.ErrReadState(subject);
        }
        bytes storage raw = s.init.intrinsicGroupBytes;
        _intrinsicMemberLength(raw, subject);
        return StorageByteView.slice(raw, 0, raw.length, subject);
    }

    function getRecord(StateStore.Store storage s, bytes32 recordId)
        internal
        view
        returns (bytes32 typeSchemaId, bytes memory canonicalBody, uint64 firstAdmitOrdinal)
    {
        _requireInitialized(s, recordId);
        StateStore.RecordRow storage row = s.records[recordId];
        if (row.recordOrdinal == 0) {
            if (row.typeId != 0 || row.firstAdmissionOrdinal != 0 || row.body.length != 0) {
                revert StorageByteView.ErrReadState(recordId);
            }
            return (0, new bytes(0), 0);
        }
        _validOrdinal(row.recordOrdinal, s.count.records, recordId);
        _validAdmission(row.firstAdmissionOrdinal, s.count.admissions, recordId);
        StateStore.TypeRow storage typeRow = s.types[row.typeId];
        if (typeRow.typeOrdinal == 0) revert StorageByteView.ErrReadState(recordId);
        _validOrdinal(typeRow.typeOrdinal, s.count.types, recordId);
        uint256 n = row.body.length;
        if (n > 8192) revert StorageByteView.ErrReadState(recordId);
        return (row.typeId, StorageByteView.slice(row.body, 0, n, recordId), row.firstAdmissionOrdinal);
    }

    function getEnvelope(StateStore.Store storage s, bytes32 envelopeId)
        internal
        view
        returns (
            bytes memory canonicalUnsignedEnvelope,
            uint48 envelopeOrdinal,
            uint16 leafCount,
            bytes32 principalId,
            uint64 authEpoch
        )
    {
        EnvelopeMetadata memory metadata = _envelopeMetadata(s, envelopeId);
        if (metadata.ordinal == 0) {
            return (new bytes(0), 0, 0, 0, 0);
        }
        canonicalUnsignedEnvelope = StorageByteView.slice(
            s.envelopes[envelopeId].canonicalUnsignedEnvelope, 0, metadata.byteLength, envelopeId
        );
        // Values are bounded before both narrowings.
        // forge-lint: disable-next-line(unsafe-typecast)
        envelopeOrdinal = uint48(metadata.ordinal);
        leafCount = metadata.leafCount;
        principalId = metadata.principalId;
        authEpoch = metadata.authEpoch;
    }

    function _hydrate(
        StateStore.Store storage s,
        bytes32 envelopeId,
        uint16 leafIndex,
        uint64 expectedOrdinal,
        uint256 lifecycle,
        bytes32 subject
    ) private view returns (HydratedOccurrence memory occurrence, uint64 authEpoch) {
        if (lifecycle == 0) revert StorageByteView.ErrReadState(subject);
        // Lifecycle status occupies the validated low byte.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint8 status = uint8(lifecycle);
        // Both values are masked to their declared u48 packed ranges before narrowing.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 ordinal = uint64((lifecycle >> 8) & ORDINAL_MAX);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 revokedAtOrdinal = uint64((lifecycle >> 56) & ORDINAL_MAX);
        if (
            lifecycle >> 104 != 0 || ordinal == 0 || ordinal >= ORDINAL_MAX || ordinal > s.count.admissions
                || (expectedOrdinal != 0 && ordinal != expectedOrdinal) || (status == 1 && revokedAtOrdinal != 0)
                || (status == 2
                    && (revokedAtOrdinal <= ordinal
                        || revokedAtOrdinal > s.count.admissions
                        || revokedAtOrdinal >= ORDINAL_MAX)) || (status != 1 && status != 2)
        ) revert StorageByteView.ErrReadState(subject);

        StateStore.AdmissionRow storage admission = s.admissions[ordinal];
        uint256 packed = admission.packed;
        if (admission.envelopeId == 0 || admission.envelopeId != envelopeId || packed >> 112 != 0) {
            revert StorageByteView.ErrReadState(subject);
        }
        // All three values are masked to their packed widths before narrowing.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 loggedLeaf = uint16(packed);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 typeOrdinal = uint64((packed >> 16) & ORDINAL_MAX);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 principalOrdinal = uint64((packed >> 64) & ORDINAL_MAX);
        if (loggedLeaf != leafIndex) revert StorageByteView.ErrReadState(subject);
        _validOrdinal(typeOrdinal, s.count.types, subject);
        _validOrdinal(principalOrdinal, s.count.principals, subject);

        EnvelopeMetadata memory envelope = _envelopeMetadataChecked(s, envelopeId, subject);
        if (leafIndex >= envelope.leafCount || s.envelopeIds[envelope.ordinal] != envelopeId) {
            revert StorageByteView.ErrReadState(subject);
        }
        bytes32 recordId = bytes32(
            StorageByteView.word(s.envelopes[envelopeId].canonicalUnsignedEnvelope, 256 + 32 * leafIndex, subject)
        );
        StateStore.RecordRow storage record = s.records[recordId];
        _validOrdinal(record.recordOrdinal, s.count.records, subject);
        _validAdmissionAt(record.firstAdmissionOrdinal, ordinal, s.count.admissions, subject);
        if (record.typeId == 0 || s.recordIds[record.recordOrdinal] != recordId) {
            revert StorageByteView.ErrReadState(subject);
        }

        bytes32 typeSchemaId = s.typeIds[typeOrdinal];
        StateStore.TypeRow storage typeRow = s.types[typeSchemaId];
        if (typeSchemaId == 0 || record.typeId != typeSchemaId || typeRow.typeOrdinal != typeOrdinal) {
            revert StorageByteView.ErrReadState(subject);
        }
        _validOrdinal(typeRow.typeOrdinal, s.count.types, subject);
        if (typeSchemaId == s.init.metaTypeId) {
            if (
                typeRow.typeOrdinal != 1 || typeRow.admittedAtOrdinal != 0 || typeRow.groupRecordId != 0
                    || typeRow.memberIndex != 0
            ) revert StorageByteView.ErrReadState(subject);
        } else {
            _validAdmissionAt(typeRow.admittedAtOrdinal, ordinal, s.count.admissions, subject);
        }

        bytes32 principalId = s.principalIds[principalOrdinal];
        StateStore.PrincipalRow storage principal = s.principals[principalId];
        if (principalId == 0 || principalId != envelope.principalId || principal.principalOrdinal != principalOrdinal) {
            revert StorageByteView.ErrReadState(subject);
        }
        _validOrdinal(principal.principalOrdinal, s.count.principals, subject);
        _validAdmissionAt(principal.firstAdmissionOrdinal, ordinal, s.count.admissions, subject);

        occurrence = HydratedOccurrence(
            envelopeId, leafIndex, recordId, typeSchemaId, principalId, status, ordinal, revokedAtOrdinal
        );
        authEpoch = envelope.authEpoch;
    }

    function _acceptingBatch(StateStore.Store storage s, uint64 ordinal, bytes32 subject)
        private
        view
        returns (BatchMetadata memory candidate)
    {
        uint64 highWater = s.count.admissions;
        uint64 batchCount = s.count.batches;
        if (batchCount == 0 || batchCount >= ORDINAL_MAX || batchCount > highWater) {
            revert StorageByteView.ErrReadState(subject);
        }
        ProbeBudget memory budget;
        uint64 lo = 1;
        uint64 hi = batchCount;
        uint64 cachedId;
        BatchMetadata memory cached;
        while (lo < hi) {
            uint64 mid = lo + (hi - lo + 1) / 2;
            cached = _batchProbe(s, mid, highWater, subject, budget);
            cachedId = mid;
            if (cached.first <= ordinal) lo = mid;
            else hi = mid - 1;
        }
        if (cachedId == lo) candidate = cached;
        else candidate = _batchProbe(s, lo, highWater, subject, budget);
        uint256 candidateEnd = uint256(candidate.first) + candidate.count;
        if (candidate.first > ordinal || ordinal >= candidateEnd) revert StorageByteView.ErrReadState(subject);

        BatchMetadata memory previous;
        if (lo > 1) {
            if (cachedId == lo - 1) previous = cached;
            else previous = _batchProbe(s, lo - 1, highWater, subject, budget);
            if (uint256(previous.first) + previous.count != candidate.first) {
                revert StorageByteView.ErrReadState(subject);
            }
        }
        BatchMetadata memory nextBatch;
        if (lo < batchCount) {
            if (cachedId == lo + 1) nextBatch = cached;
            else nextBatch = _batchProbe(s, lo + 1, highWater, subject, budget);
            if (candidateEnd != nextBatch.first) revert StorageByteView.ErrReadState(subject);
        }

        BatchMetadata memory firstBatch;
        if (lo == 1) firstBatch = candidate;
        else if (lo == 2) firstBatch = previous;
        else if (cachedId == 1) firstBatch = cached;
        else firstBatch = _batchProbe(s, 1, highWater, subject, budget);
        if (firstBatch.first != 1) revert StorageByteView.ErrReadState(subject);

        BatchMetadata memory lastBatch;
        if (lo == batchCount) lastBatch = candidate;
        else if (lo + 1 == batchCount) lastBatch = nextBatch;
        else if (cachedId == batchCount) lastBatch = cached;
        else lastBatch = _batchProbe(s, batchCount, highWater, subject, budget);
        if (uint256(lastBatch.first) + lastBatch.count != uint256(highWater) + 1) {
            revert StorageByteView.ErrReadState(subject);
        }
    }

    function _batchProbe(
        StateStore.Store storage s,
        uint64 batchId,
        uint64 highWater,
        bytes32 subject,
        ProbeBudget memory budget
    ) private view returns (BatchMetadata memory result) {
        if (++budget.used > 64) revert StorageByteView.ErrReadState(subject);
        StateStore.BatchRow storage row = s.batches[batchId];
        uint256 meta = row.meta;
        // All fields are masked to their packed widths before narrowing.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 first = uint64(meta & ORDINAL_MAX);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 count = uint16((meta >> 48) & type(uint16).max);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint48 admittedAtBlock = uint48((meta >> 64) & ORDINAL_MAX);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint32 revision = uint32((meta >> 112) & type(uint32).max);
        if (
            meta >> 144 != 0 || first == 0 || first >= ORDINAL_MAX || count == 0 || count > 64 || revision != 1
                || uint256(first) + count > uint256(highWater) + 1
        ) revert StorageByteView.ErrReadState(subject);
        result = BatchMetadata(first, count, admittedAtBlock, row.authorityBasis, row.authorityCodehash);
    }

    function _envelopeMetadata(StateStore.Store storage s, bytes32 envelopeId)
        private
        view
        returns (EnvelopeMetadata memory)
    {
        _requireInitialized(s, envelopeId);
        return _envelopeMetadataChecked(s, envelopeId, envelopeId);
    }

    function _envelopeMetadataChecked(StateStore.Store storage s, bytes32 envelopeId, bytes32 subject)
        private
        view
        returns (EnvelopeMetadata memory metadata)
    {
        StateStore.EnvelopeRow storage row = s.envelopes[envelopeId];
        uint256 n = row.canonicalUnsignedEnvelope.length;
        if (row.envelopeOrdinal == 0) {
            if (n != 0) revert StorageByteView.ErrReadState(subject);
            return metadata;
        }
        _validOrdinal(row.envelopeOrdinal, s.count.envelopes, subject);
        bytes storage raw = row.canonicalUnsignedEnvelope;
        if (n < 288 || n > 2304) revert StorageByteView.ErrReadState(subject);
        uint256 profile = StorageByteView.word(raw, 0, subject);
        bytes32 principalId = bytes32(StorageByteView.word(raw, 32, subject));
        uint256 authorityRef = StorageByteView.word(raw, 64, subject);
        uint256 epoch = StorageByteView.word(raw, 96, subject);
        uint256 notAfter = StorageByteView.word(raw, 160, subject);
        uint256 arrayOffset = StorageByteView.word(raw, 192, subject);
        uint256 count = StorageByteView.word(raw, 224, subject);
        if (
            profile != 1 || authorityRef != 0 || epoch != 0 || notAfter > type(uint64).max || arrayOffset != 224
                || count == 0 || count > 64 || n != 256 + 32 * count
        ) revert StorageByteView.ErrReadState(subject);
        // Count and epoch were bounded before narrowing.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint16 narrowedCount = uint16(count);
        // forge-lint: disable-next-line(unsafe-typecast)
        uint64 narrowedEpoch = uint64(epoch);
        metadata = EnvelopeMetadata(row.envelopeOrdinal, narrowedCount, principalId, narrowedEpoch, n);
    }

    function _requireOccurrenceCounters(StateStore.Store storage s, bytes32 subject) private view {
        _requireInitialized(s, subject);
        if (
            s.typeIds[1] != s.init.metaTypeId || s.count.records >= ORDINAL_MAX || s.count.envelopes >= ORDINAL_MAX
                || s.count.principals >= ORDINAL_MAX || s.count.admissions >= ORDINAL_MAX
        ) revert StorageByteView.ErrReadState(subject);
    }

    function _requireRequestedOrdinal(uint64 ordinal, uint64 highWater) private pure {
        if (ordinal == 0 || ordinal >= ORDINAL_MAX || ordinal > highWater) revert ErrReadOrdinal(ordinal);
    }

    function _validAdmissionAt(uint64 ordinal, uint64 at, uint64 current, bytes32 subject) private pure {
        if (ordinal == 0 || ordinal >= ORDINAL_MAX || current >= ORDINAL_MAX || ordinal > at || ordinal > current) {
            revert StorageByteView.ErrReadState(subject);
        }
    }

    function _requireInitialized(StateStore.Store storage s, bytes32 subject) private view {
        bytes32 metaTypeId = s.init.metaTypeId;
        StateStore.TypeRow storage meta = s.types[metaTypeId];
        if (s.init.realmId == 0 || metaTypeId == 0 || meta.typeOrdinal == 0) {
            revert StateKernel.InvalidInitialization();
        }
        if (
            meta.typeOrdinal != 1 || meta.admittedAtOrdinal != 0 || meta.groupRecordId != 0 || meta.memberIndex != 0
                || s.count.types == 0 || s.count.types >= ORDINAL_MAX
        ) revert StorageByteView.ErrReadState(subject);
    }

    function _validOrdinal(uint64 ordinal, uint64 retained, bytes32 subject) private pure {
        if (ordinal == 0 || ordinal >= ORDINAL_MAX || retained >= ORDINAL_MAX || ordinal > retained) {
            revert StorageByteView.ErrReadState(subject);
        }
    }

    function _validAdmission(uint64 ordinal, uint64 current, bytes32 subject) private pure {
        if (ordinal == 0 || ordinal >= ORDINAL_MAX || current >= ORDINAL_MAX || ordinal > current) {
            revert StorageByteView.ErrReadState(subject);
        }
    }

    function _intrinsicBlob(StateStore.Store storage s, bytes32 subject) private view returns (bytes memory) {
        bytes storage raw = s.init.intrinsicGroupBytes;
